# Verify dependencies are satisfied
tasks_info = {
    "T001": {"depends_on": [], "start": "08:00", "duration": 20},
    "T003": {"depends_on": ["T002"], "start": "08:20", "duration": 15},
    "T004": {"depends_on": ["T002", "T003"], "start": "08:35", "duration": 120},
    "T005": {"depends_on": ["T001", "T002"], "start": "11:50", "duration": 45},
    "T007": {"depends_on": ["T004"], "start": "11:10", "duration": 15},
    "T008": {"depends_on": ["T004", "T007"], "start": "11:40", "duration": 10},
    "T009": {"depends_on": ["T004"], "start": "11:10", "duration": 30},
}

# Track completion times
completion = {}

def time_to_minutes(time_str):
    parts = time_str.split(":")
    if len(parts) == 2:
        return int(parts[0]) * 60 + int(parts[1])
    return time_to_minutes(parts[0]) + int(parts[1])

# Process tasks in order
task_order = ["T001", "T003", "T004", "T005", "T007", "T008", "T009"]

for task_id in task_order:
    if task_id in tasks_info:
        task = tasks_info[task_id]
        start = time_to_minutes(task["start"])
        duration = task["duration"]
        end = start + duration

        # Check dependencies
        for dep in task["depends_on"]:
            if dep not in completion:
                print(f"ERROR: {task_id} depends on {dep} which hasn't been completed yet")
            elif completion[dep] > end:
                print(f"WARNING: {task_id} depends on {dep} but {dep} completes after {task_id} starts")
                print(f"   {dep} completes at {completion[dep]}:{completion[dep]%60}")
                print(f"   {task_id} starts at {task['start']}")
        else:
            completion[task_id] = end
            print(f"✓ {task_id} completes at {completion[task_id]//60}:{(completion[task_id]%60):02d}")

print("\n=== Dependency verification complete ===")
EOF
